function validate([mat, k]) {
  if (!Array.isArray(mat) || mat.length < 1 || mat.length > 40) return 'mat needs 1 to 40 rows.';
  const n = mat[0].length;
  if (n < 1 || n > 40) return 'Each row needs 1 to 40 values.';
  for (const row of mat) {
    if (row.length !== n) return 'All rows must have the same length.';
    for (let j = 0; j < n; j++) {
      if (!Number.isInteger(row[j]) || row[j] < 1 || row[j] > 5000) return 'Each value is an integer from 1 to 5000.';
      if (j > 0 && row[j] < row[j - 1]) return 'Each row must be sorted in non-decreasing order.';
    }
  }
  if (!Number.isInteger(k) || k < 1 || k > Math.min(200, n ** mat.length)) return 'k is between 1 and min(200, n^m).';
  return null;
}

