function kthSmallest(mat, k) {
  function push(heap, item) {
    heap.push(item);
    let child = heap.length - 1;
    while (child > 0) {
      const parent = (child - 1) >> 1;
      if (heap[parent][0] <= heap[child][0]) break;
      [heap[parent], heap[child]] = [heap[child], heap[parent]];
      child = parent;
    }
  }

  function pop(heap) {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let parent = 0;
      while (true) {
        const left = 2 * parent + 1;
        const right = left + 1;
        let smallest = parent;
        if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
        if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
        if (smallest === parent) break;
        [heap[parent], heap[smallest]] = [heap[smallest], heap[parent]];
        parent = smallest;
      }
    }
    return top;
  }

  let sums = [0];
  for (const row of mat) {
    const heap = [];
    for (let i = 0; i < sums.length; i++) {
      push(heap, [sums[i] + row[0], i, 0]);
    }
    const next = [];
    while (next.length < k && heap.length > 0) {
      const [sum, i, j] = pop(heap);
      next.push(sum);
      if (j + 1 < row.length) {
        push(heap, [sums[i] + row[j + 1], i, j + 1]);
      }
    }
    sums = next;
  }
  return sums[k - 1];
}

