function kthSmallest(mat, k) {
  // Every combination of a kept partial sum with every row value, sorted; only the k smallest can matter later.
  let all = [0];
  for (const row of mat) {
    const grown = [];
    for (const total of all) for (const value of row) grown.push(total + value);
    grown.sort((a, b) => a - b);
    all = grown.slice(0, k);
  }
  return all[k - 1];
}

