  const top = large ? 5000 : [3, 10, 5000][Math.floor(rand() * 3)];
  const mat = Array.from({ length: m }, () => Array.from({ length: n }, () => 1 + Math.floor(rand() * top)).sort((a, b) => a - b));
  const limit = Math.min(200, n ** m);
  const k = large ? limit - Math.floor(rand() * 20) : 1 + Math.floor(rand() * limit);
  return [mat, k];
}
